sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        /*
		MSSCUSTODY-5485 && MSSCUSTODY-5494 Artifacts Included: 
        1) Business Rule: MSS Trade Amendment -  Create Payload
        2) Script Include: x_hsb11_mss_c_proc.MSSCustodyAmendUtils
        3) Method: createPayloadBulkTradeAmendment
		4) Script Include : x_hsb11_mss_c_ghss.MSSCustomeGHSSAmendUtils
		5) Method : createOutBoundRecSingleAmend
        */

        var bulkRec = current.bulk_id;
        var tradeCount = parseInt(current.bulk_id.active_trade_count);
        var ghssHandlerTask = current.sys_id;
        var ghssCaseID = current.trade_case_id.sys_id;
        var bulkFieldGrp = current.bulk_id.bulk_field_group ? current.bulk_id.bulk_field_group.toString() : "";
        //handing the checker failure if the checker is failed at the 
        var taskStatus = current.amend_checker_decision.toString();
        var outcome = current.outcome ? current.outcome.toString() : "";

        //handing the checker failure if the checker is failed at the 

        if (!bulkFieldGrp) { //Single Trade Amendment

            if (outcome == 'No Amendment Required') {
                //No amendment Required MSSCUSTODY-8725
                try {
                    var bulkStatus = 'false';
                    if (tradeCount > 1) {
                        bulkStatus = 'true';
                    }
                    new x_hsb11_mss_c_proc.MSSCustodyAmendUtils().createNoTradeAmendmentPayload(ghssHandlerTask, taskStatus,bulkStatus);
                } catch (ex) {
                    gs.info("Error from Business rule MSS Amend Create Payload - No Amend " + ex);
                }
                //No amendment Required MSSCUSTODY-8725

            } else {
                //Single Trade Amendment
                try {
                    gs.info('Loop 1 Amend generated for ' + ghssHandlerTask);
                    new x_hsb11_mss_c_proc.MSSCustodyAmendUtils().createPayloadSingleTradeAmendment(bulkRec, ghssHandlerTask, taskStatus);
                } catch (ex) {
                    gs.info("Error from Business rule MSS Amend Create Payload - Single Amend " + ex);
                }
                //Single Trade Amendment
            }

        } else { //Bulk Trade Amendment
            try {
                gs.info('Loop 2 Amend');
                new x_hsb11_mss_c_proc.MSSCustodyAmendUtils().createPayloadBulkTradeAmendment(bulkRec, bulkFieldGrp, ghssHandlerTask, taskStatus);
            } catch (ex) {
                gs.info("Error from Business rule MSS Amend Create Payload - Bulk Amend " + ex);
            }
        }

    } catch (ex) {

        gs.info('Details of the task + ' + ghssHandlerTask + ' tradeCount ' + tradeCount + ' ghssCaseID ' + ghssCaseID + 'taskStatus ' + taskStatus);
        gs.info("Error from Business rule MSS Amend Create Payload " + ex);
    }

})(current, previous);
